mapper.select:
SELECT DATE(COALESCE(ke.final_at, ke.provisional_at)) AS statDate, SUM(ke.provisional_amount) AS provisionalAmount, SUM(ke.final_amount) AS finalAmount FROM krw_exchange ke JOIN account a ON a.account_id = ke.account_id JOIN customer c ON c.customer_id = a.customer_id
AND (a.account_no LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))
AND COALESCE(ke.final_at, ke.provisional_at) >= #{startDateTime}
AND COALESCE(ke.final_at, ke.provisional_at) <= #{endDateTime}
GROUP BY statDate ORDER BY statDate

SELECT p.periodLabel AS periodLabel, COALESCE(SUM(fso.sellAmount), 0) AS sellAmount FROM ( SELECT 1 AS ord, '1~5월 (100%)' AS periodLabel UNION ALL SELECT 2, '6~7월 (80%)' UNION ALL SELECT 3, '8~12월 (50%)' ) p LEFT JOIN ( SELECT CASE WHEN MONTH(so.processed_at) BETWEEN 1 AND 5 THEN 1 WHEN MONTH(so.processed_at) BETWEEN 6 AND 7 THEN 2 ELSE 3 END AS bucketOrd,
AS sellAmount FROM sell_order so LEFT JOIN krw_exchange ke ON ke.order_id = so.order_id JOIN account a ON a.account_id = so.account_id JOIN customer c ON c.customer_id = a.customer_id
so.status != 'REJECTED'
AND (a.account_no LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))
AND so.processed_at >= #{startDateTime} AND so.processed_at <= #{endDateTime}
) fso ON fso.bucketOrd = p.ord GROUP BY p.ord, p.periodLabel ORDER BY p.ord
